pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint v, uint _decimals) public {
        vm.assume(_tos.length > 0);
        // Bound _decimals to avoid overflow
        vm.assume(_decimals <= 77);
        // Bound v to avoid overflow
        vm.assume(v <= type(uint128).max);

        // We cannot check internal state, so we check that a successful call always returns true
        // In C reference, if it succeeds it returns true. In buggy version, it can return false.
        (bool success,) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v, _decimals));
        if (success) {
            // Reference never returns false on success
        } else {
            // If it reverts, the difference is not observable
        }
        // Instead, we can compare the return value directly if we use a try/catch
        try c.transfer(from, caddress, _tos, v, _decimals) returns (bool result) {
            assertTrue(result, "transfer should not return false");
        } catch {
            // Revert is fine; property holds vacuously
        }
    }
}

